-- GENERATED by tools/gen_tests.py from the assembly below. Edit the program
-- there and re-run the script; expected values come from its ISA simulator.
--
--   0x00: lui  x1, 0x80000
--   0x04: addi x1, x1, -1   # 0x7FFFFFFF (INT_MAX)
--   0x08: add  x2, x1, x1   # 0xFFFFFFFE
--   0x0C: addi x3, x0, 1  
--   0x10: add  x4, x1, x3   # INT_MAX + 1 wraps to 0x80000000
--   0x14: slli x5, x1, 5    # 0xFFFFFFE0
--   0x18: sub  x6, x4, x3   # INT_MIN - 1 wraps to 0x7FFFFFFF
--   0x1C: lui  x9, 0x80000
--   0x20: srai x10, x9, 1   # 0xC0000000
--   0x24: srli x11, x9, 31  # 1
--   0x28: sltu x12, x9, x3  # 0x80000000 <u 1 -> 0
--   0x2C: slt  x13, x9, x3  # INT_MIN < 1 -> 1
--   0x30: add  x14, x9, x9  # 0
--   0x34: jal x0, halt      # end of program
-- =============================================================================
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

library work;
use work.tb_pkg.all;

entity tb_overflow_edge is
end entity tb_overflow_edge;

architecture sim of tb_overflow_edge is
    signal clk        : std_logic := '0';
    signal rst        : std_logic := '1';
    signal dbg_pc     : std_logic_vector(31 downto 0);
    signal dbg_instr  : std_logic_vector(31 downto 0);
    signal dbg_reg_we : std_logic;
    signal dbg_reg_wa : std_logic_vector(4 downto 0);
    signal dbg_reg_wd : std_logic_vector(31 downto 0);

    -- Shadow register file built from the write-back port, plus the cycle
    -- (counted from reset release) of each register's latest write.
    signal regs       : reg_array_t := (others => (others => '0'));
    signal wcycle     : int_array_t := (others => -1);
    signal cycle      : integer := 0;
    signal clear_regs : std_logic := '0';

    constant PROG : prog_t := (
         0 => x"800000B7",
         1 => x"FFF08093",
         2 => x"00108133",
         3 => x"00100193",
         4 => x"00308233",
         5 => x"00509293",
         6 => x"40320333",
         7 => x"800004B7",
         8 => x"4014D513",
         9 => x"01F4D593",
        10 => x"0034B633",
        11 => x"0034A6B3",
        12 => x"00948733",
        13 => x"0000006F"
    );
    constant HEX_FILE : string := write_hex("/tmp/tb_overflow_edge.hex", PROG);

begin
    clk <= not clk after CLK_PERIOD / 2;

    dut: entity work.pipeline_top
        generic map (MEM_DEPTH => 256, IMEM_INIT => HEX_FILE)
        port map (clk => clk, rst => rst,
                  dbg_pc => dbg_pc, dbg_instr => dbg_instr,
                  dbg_reg_we => dbg_reg_we,
                  dbg_reg_wa => dbg_reg_wa,
                  dbg_reg_wd => dbg_reg_wd);

    process(clk)
    begin
        if rising_edge(clk) then
            if rst = '1' then
                cycle <= 0;
            else
                cycle <= cycle + 1;
            end if;
            if clear_regs = '1' then
                regs   <= (others => (others => '0'));
                wcycle <= (others => -1);
            elsif dbg_reg_we = '1' and unsigned(dbg_reg_wa) /= 0 then
                regs(to_integer(unsigned(dbg_reg_wa)))   <= dbg_reg_wd;
                wcycle(to_integer(unsigned(dbg_reg_wa))) <= cycle;
            end if;
        end if;
    end process;

    process
        variable errors : natural := 0;
    begin
        rst <= '1';
        wait for 3 * CLK_PERIOD;
        rst <= '0';
        wait for 72 * CLK_PERIOD;

        check_reg(regs, 1, x"7FFFFFFF", "x1", errors);
        check_reg(regs, 2, x"FFFFFFFE", "x2", errors);
        check_reg(regs, 4, x"80000000", "x4", errors);
        check_reg(regs, 5, x"FFFFFFE0", "x5", errors);
        check_reg(regs, 6, x"7FFFFFFF", "x6", errors);
        check_reg(regs, 10, x"C0000000", "x10", errors);
        check_reg(regs, 11, x"00000001", "x11", errors);
        check_reg(regs, 12, x"00000000", "x12", errors);
        check_reg(regs, 13, x"00000001", "x13", errors);
        check_reg(regs, 14, x"00000000", "x14", errors);

        finish_test("tb_overflow_edge", errors);
        wait;
    end process;
end architecture sim;
